def mrn_is_valid(mrn: str) -> bool:
    if len(mrn) != 8 or not mrn.isdigit():
        return False
    body, check = mrn[:7], int(mrn[7])
    return sum(int(d) * (i + 2) for i, d in enumerate(body)) % 11 % 10 == check

