import hashlib, json

def verify(path):
    prev = ""
    for line in open(path):
        row = json.loads(line)
        body = json.dumps(row["entry"], sort_keys=True)
        if row["prev"] != prev or hashlib.sha256((prev + body).encode()).hexdigest() != row["hash"]:
            raise RuntimeError("audit chain broken")
        prev = row["hash"]

