BATCH_SIZE = 500

def consented_batches(participants, study_id, is_consented):
    batch = []
    for p in participants:
        if is_consented(p, study_id):
            batch.append(p.mrn)
        if len(batch) == BATCH_SIZE:
            yield batch
            batch = []
    if batch:
        yield batch

